import dayjs from 'dayjs';
import utc from 'dayjs/plugin/utc';
import { useState } from 'react';
import { Button, Code, Group, Stack, Text } from '@mantine/core';
import { useForm, type FormErrors } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { ErrorSummary } from './ErrorSummary';
import { EventFields } from './EventFields';
import { focusField } from './focusField';
import { buildPayload } from './payload';
import { formatOccurrence, getRecurrenceRule, upcomingOccurrences } from './recurrence';
import { RecurrenceFields } from './RecurrenceFields';
import type { RecurringEventPayload, RecurringEventValues } from './types';
import { useDependentFields } from './useDependentFields';
import { getDefaultTimezone, RULES } from './validation';

dayjs.extend(utc);

function describeFirstOccurrence(values: RecurringEventValues) {
  const rule = getRecurrenceRule(values);
  const first = rule ? upcomingOccurrences(rule, values.exceptions, 1)[0] : dayjs.utc(values.start);
  return first ? formatOccurrence(first, values.allDay) : 'No occurrences';
}

interface RecurringEventFormProps {
  onSubmit?: (payload: RecurringEventPayload) => void;
}

export function RecurringEventForm({ onSubmit }: RecurringEventFormProps) {
  const [payload, setPayload] = useState<RecurringEventPayload | null>(null);
  const [showSummary, setShowSummary] = useState(false);

  const form = useForm<RecurringEventValues, RecurringEventPayload>({
    name: 'recurring-event',
    initialValues: {
      title: '',
      description: '',
      allDay: false,
      start: null,
      end: null,
      timezone: getDefaultTimezone(),
      location: '',
      repeats: false,
      frequency: 'weekly',
      interval: 1,
      weekdays: [],
      monthlyMode: 'day',
      ends: 'never',
      count: 10,
      until: null,
      exceptions: [],
    },
    validateInputOnBlur: ['title', 'interval', 'count'],
    validate: RULES,
    transformValues: buildPayload,
  });

  const { markEdited } = useDependentFields(form);

  const handleSubmit = (event: RecurringEventPayload) => {
    setShowSummary(false);
    setPayload(event);
    onSubmit?.(event);
    notifications.show({
      title: 'Event created',
      message: `${event.title} · ${describeFirstOccurrence(form.getValues())}`,
    });
  };

  const handleErrors = (errors: FormErrors) => {
    setShowSummary(true);
    focusField(form, Object.keys(errors)[0]);
  };

  return (
    <Stack gap="xl">
      <form onSubmit={form.onSubmit(handleSubmit, handleErrors)} noValidate>
        <Stack>
          {showSummary && <ErrorSummary form={form} />}
          <EventFields form={form} onEndEdit={() => markEdited('end')} />
          <RecurrenceFields form={form} onWeekdaysEdit={() => markEdited('weekdays')} />
          <Group justify="flex-end">
            {/* preventDefault keeps focus in the field, so its blur error does not shift the button */}
            <Button type="submit" onMouseDown={(event) => event.preventDefault()}>
              Create event
            </Button>
          </Group>
        </Stack>
      </form>

      {payload && (
        <div>
          <Text size="sm" fw={500} mb="xs">
            Event JSON
          </Text>
          <Code block aria-label="Event JSON">
            {JSON.stringify(payload, null, 2)}
          </Code>
        </div>
      )}
    </Stack>
  );
}

import dayjs from 'dayjs';
import { NumberInput, Radio, Stack } from '@mantine/core';
import { MaskedDateInput } from '@mantine/dates';
import type { RecurringEventFormType } from './types';
import { ENDS_OPTIONS } from './validation';

export function EndsFields({ form }: { form: RecurringEventFormType }) {
  const ends = form.useWatchValue('ends');
  const start = form.useWatchValue('start');

  return (
    <Stack gap="xs">
      <Radio.Group label="Ends" {...form.getInputProps('ends')}>
        <Stack gap="xs" mt="xs">
          {ENDS_OPTIONS.map((option) => (
            <Radio key={option.value} value={option.value} label={option.label} />
          ))}
        </Stack>
      </Radio.Group>

      {ends === 'after' && (
        <NumberInput
          label="Occurrences"
          placeholder="Number of occurrences"
          min={1}
          max={500}
          allowDecimal={false}
          allowNegative={false}
          maw={240}
          withAsterisk
          {...form.getInputProps('count')}
        />
      )}

      {ends === 'on' && (
        <MaskedDateInput
          label="End date"
          minDate={start ? dayjs(start).add(1, 'day').format('YYYY-MM-DD') : undefined}
          maw={240}
          withAsterisk
          dayInputLabel="End date day"
          monthInputLabel="End date month"
          yearInputLabel="End date year"
          {...form.getInputProps('until')}
        />
      )}
    </Stack>
  );
}

import { Alert, Anchor, Stack } from '@mantine/core';
import { focusField } from './focusField';
import type { RecurringEventFormType } from './types';

export function ErrorSummary({ form }: { form: RecurringEventFormType }) {
  const entries = Object.entries(form.errors);

  if (entries.length === 0) {
    return null;
  }

  return (
    <Alert variant="default" color="red" title="There is a problem">
      <Stack gap={4} align="flex-start">
        {entries.map(([path, message]) => (
          <Anchor
            key={path}
            component="button"
            type="button"
            size="sm"
            onClick={() => focusField(form, path)}
          >
            {message}
          </Anchor>
        ))}
      </Stack>
    </Alert>
  );
}

